import java.net.HttpURLConnection;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Reads drop names from the event Sheet; it never writes to Google. */
final class GoogleSheetDrops
{
    private static final String SCOPE = "https://www.googleapis.com/auth/spreadsheets.readonly";
    private static final Pattern PATH = Pattern.compile("^/spreadsheets/d/([A-Za-z0-9_-]{20,128})(?:/.*)?$");
    private static final Pattern GID = Pattern.compile("(?:^|&)gid=([0-9]{1,20})(?:&|$)");
    private static final int MAX_BYTES = 1024 * 1024;
    private static final int MAX_ITEMS = 500;
    private static GoogleCredentials credentials;

    private GoogleSheetDrops() { }

    static String sheetId(String url)
    {
        if (url == null || url.length() > 2000) return null;
        try
        {
            URI uri = URI.create(url.trim());
            if (!"https".equalsIgnoreCase(uri.getScheme()) || !"docs.google.com".equalsIgnoreCase(uri.getHost())
                || uri.getUserInfo() != null || (uri.getPort() != -1 && uri.getPort() != 443)) return null;
            Matcher match = PATH.matcher(uri.getRawPath());
            return match.matches() ? match.group(1) : null;
        }
        catch (RuntimeException ex) { return null; }
    }

    static Set<String> fetch(String link) throws IOException
    {
        String id = sheetId(link);
        if (id == null) throw new IOException("Geen ondersteunde Google Sheets-link");
        // Een openbare Sheet heeft geen Google-account of service-account nodig.
        // Probeer die route eerst, zodat de eventbeheerder niets extra's hoeft te delen.
        try
        {
            URI publicCsv = publicCsv(link, id);
            return parseCsv(new String(read(publicCsv, null), StandardCharsets.UTF_8));
        }
        catch (IOException publicFailure)
        {
            return fetchPrivate(id, publicFailure);
        }
    }

    private static URI publicCsv(String link, String id)
    {
        URI original = URI.create(link.trim());
        Matcher gid = GID.matcher(original.getRawQuery() == null ? "" : original.getRawQuery());
        String tab = gid.find() ? "gid=" + gid.group(1) : "sheet=Instellingen";
        return URI.create("https://docs.google.com/spreadsheets/d/" + id + "/gviz/tq?tqx=out:csv&" + tab);
    }

    private static Set<String> fetchPrivate(String id, IOException publicFailure) throws IOException
    {
        String jsonKey = System.getenv("DN_GOOGLE_SERVICE_ACCOUNT_JSON");
        if (jsonKey == null || jsonKey.trim().isEmpty() || jsonKey.length() > 50000)
            throw new IOException("Sheet is niet openbaar bereikbaar; deel hem openbaar of stel Google-leestoegang in", publicFailure);
        GoogleCredentials access = credentials(jsonKey);
        access.refreshIfExpired();
        if (access.getAccessToken() == null) throw new IOException("Google-leestoegang niet beschikbaar");
        URI api = URI.create("https://sheets.googleapis.com/v4/spreadsheets/" + id + "/values/Instellingen%21G3%3AH1000");
        return parse(new String(read(api, "Bearer " + access.getAccessToken().getTokenValue()), StandardCharsets.UTF_8));
    }

    private static byte[] read(URI uri, String authorization) throws IOException
    {
        HttpURLConnection connection = (HttpURLConnection) uri.toURL().openConnection();
        connection.setConnectTimeout(6000); connection.setReadTimeout(10000);
        connection.setInstanceFollowRedirects(false);
        if (authorization != null) connection.setRequestProperty("Authorization", authorization);
        try
        {
            if (connection.getResponseCode() != 200) throw new IOException("Sheet gaf HTTP " + connection.getResponseCode());
            byte[] bytes;
            try (java.io.InputStream input = connection.getInputStream()) { bytes = input.readNBytes(MAX_BYTES + 1); }
            if (bytes.length > MAX_BYTES) throw new IOException("Sheetgegevens zijn te groot");
            return bytes;
        }
        finally { connection.disconnect(); }
    }

    private static synchronized GoogleCredentials credentials(String jsonKey) throws IOException
    {
        if (credentials != null) return credentials;
        try (ByteArrayInputStream key = new ByteArrayInputStream(jsonKey.getBytes(StandardCharsets.UTF_8)))
        {
            credentials = ServiceAccountCredentials.fromStream(key).createScoped(Collections.singleton(SCOPE));
        }
        return credentials;
    }

    static Set<String> parse(String json) throws IOException
    {
        try
        {
            JsonObject data = JsonParser.parseString(json).getAsJsonObject();
            JsonArray rows = data.getAsJsonArray("values");
            if (rows == null || rows.size() < 2) throw new IOException("Geen droplijst gevonden");
            List<List<String>> table = new ArrayList<>();
            for (int i = 1; i < rows.size(); i++)
            {
                JsonElement value = rows.get(i);
                if (!value.isJsonArray()) throw new IOException("Ongeldige rij in droplijst");
                JsonArray row = value.getAsJsonArray();
                List<String> values = new ArrayList<>();
                for (JsonElement cell : row) values.add(cell.isJsonNull() ? "" : cell.getAsString());
                table.add(values);
            }
            JsonArray header = rows.get(0).getAsJsonArray();
            List<String> headerValues = new ArrayList<>();
            for (JsonElement cell : header) headerValues.add(cell.isJsonNull() ? "" : cell.getAsString());
            table.add(0, headerValues);
            return parseTable(table);
        }
        catch (IOException ex) { throw ex; }
        catch (RuntimeException ex) { throw new IOException("Sheetgegevens hebben een onbekende indeling", ex); }
    }

    static Set<String> parseCsv(String csv) throws IOException
    {
        return parseTable(csvRows(csv));
    }

    private static Set<String> parseTable(List<List<String>> rows) throws IOException
    {
        int headerRow = -1;
        int itemColumn = -1;
        for (int rowIndex = 0; rowIndex < rows.size() && headerRow == -1; rowIndex++)
        {
            List<String> row = rows.get(rowIndex);
            for (int column = 0; column + 1 < row.size(); column++)
            {
                if ("drop (bewerkbaar)".equals(row.get(column).replace("\ufeff", "").trim().toLowerCase(Locale.ROOT))
                    && "doel".equals(row.get(column + 1).trim().toLowerCase(Locale.ROOT)))
                { headerRow = rowIndex; itemColumn = column; break; }
            }
        }
        if (headerRow == -1)
            throw new IOException("Sheet heeft niet de verwachte indeling");
        Set<String> names = new LinkedHashSet<>();
        Set<String> normalized = new LinkedHashSet<>();
        for (int i = headerRow + 1; i < rows.size(); i++)
        {
            List<String> row = rows.get(i);
            String item = row.size() <= itemColumn ? "" : row.get(itemColumn).trim();
            if (item.isEmpty()) continue;
            if (item.length() > 100 || item.indexOf(';') >= 0 || item.chars().anyMatch(Character::isISOControl))
                throw new IOException("Ongeldige dropnaam in sheet");
            String key = item.replace('\u2019', '\'').toLowerCase(Locale.ROOT);
            if (!normalized.add(key) || names.size() >= MAX_ITEMS) throw new IOException("Dubbele of te veel drops in sheet");
            names.add(item);
        }
        if (names.isEmpty()) throw new IOException("Geen dropnamen gevonden");
        return Collections.unmodifiableSet(names);
    }

    private static List<List<String>> csvRows(String csv) throws IOException
    {
        List<List<String>> rows = new ArrayList<>(); List<String> row = new ArrayList<>(); StringBuilder cell = new StringBuilder(); boolean quoted = false;
        for (int i = 0; i < csv.length(); i++)
        {
            char value = csv.charAt(i);
            if (value == '"')
            {
                if (quoted && i + 1 < csv.length() && csv.charAt(i + 1) == '"') { cell.append(value); i++; }
                else quoted = !quoted;
            }
            else if (value == ',' && !quoted) { row.add(cell.toString()); cell.setLength(0); }
            else if ((value == '\n' || value == '\r') && !quoted)
            {
                if (value == '\r' && i + 1 < csv.length() && csv.charAt(i + 1) == '\n') i++;
                row.add(cell.toString()); cell.setLength(0); rows.add(row); row = new ArrayList<>();
            }
            else cell.append(value);
        }
        if (quoted) throw new IOException("Ongeldige CSV in Sheet");
        if (cell.length() > 0 || !row.isEmpty()) { row.add(cell.toString()); rows.add(row); }
        return rows;
    }
}

package nl.dutchnations.server;

import java.io.IOException;
import java.io.InputStream;
import java.io.Reader;
import java.io.StringReader;
import java.net.HttpURLConnection;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.util.Enumeration;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import javax.swing.text.MutableAttributeSet;
import javax.swing.text.html.HTML;
import javax.swing.text.html.HTMLEditorKit;
import javax.swing.text.html.parser.ParserDelegator;

/** Read-only, local-test view of the public PvM War progress. */
final class PvmWarProgress
{
    static final String SOURCE = "PVM_WAR_2026";
    private static final URI PAGE = URI.create("https://osrs-nlbe.com/author/dutch_nation/pvm-war-2026/");
    private static final int MAX_PAGE_BYTES = 2_000_000;
    private final Map<String, Slots> items;

    private PvmWarProgress(Map<String, Slots> items) { this.items = items; }

    static PvmWarProgress fetch() throws IOException
    {
        HttpURLConnection connection = (HttpURLConnection) PAGE.toURL().openConnection();
        connection.setConnectTimeout(6000);
        connection.setReadTimeout(10000);
        connection.setInstanceFollowRedirects(false);
        connection.setRequestProperty("User-Agent", "DutchNationLocalDropTest/1.0");
        try
        {
            if (connection.getResponseCode() != 200) throw new IOException("PvM War-pagina niet beschikbaar");
            byte[] page;
            try (InputStream body = connection.getInputStream()) { page = body.readNBytes(MAX_PAGE_BYTES + 1); }
            if (page.length > MAX_PAGE_BYTES) throw new IOException("PvM War-pagina te groot");
            PvmWarProgress progress = parse(new String(page, StandardCharsets.UTF_8));
            // Reject error pages or changed layouts; missing items must never silently become zero.
            if (progress.items.size() < 100 || progress.lookup("Jar Tier 1") == null
                || progress.lookup("Dragon claws") == null)
                throw new IOException("PvM War-pagina heeft een onbekende indeling");
            return progress;
        }
        finally { connection.disconnect(); }
    }

    static PvmWarProgress parse(String html) throws IOException
    {
        Map<String, Slots> result = new HashMap<>();
        HTMLEditorKit.ParserCallback callback = new HTMLEditorKit.ParserCallback()
        {
            String item;
            int cells, approved, waiting;
            boolean title, invalid;

            @Override public void handleStartTag(HTML.Tag tag, MutableAttributeSet attributes, int position)
            {
                if (tag == HTML.Tag.TR)
                {
                    item = attr(attributes, "data-item"); cells = 0; approved = 0; waiting = 0;
                    title = false; invalid = false;
                }
                else if (item != null && tag == HTML.Tag.TD)
                {
                    cells++;
                    if (cells > 1)
                    {
                        String css = attr(attributes, "class");
                        css = css == null ? "" : css.trim();
                        if ("approved".equals(css)) approved++;
                        else if ("waiting".equals(css)) waiting++;
                        else if (!css.isEmpty()) invalid = true;
                    }
                }
                else if (item != null && tag == HTML.Tag.SPAN)
                {
                    String css = attr(attributes, "class");
                    if (css != null && (" " + css + " ").contains(" item-name__title ")) title = true;
                }
            }

            @Override public void handleEndTag(HTML.Tag tag, int position)
            {
                if (tag == HTML.Tag.TR && item != null)
                {
                    if (title && cells == 4 && !invalid && approved + waiting <= 3)
                    {
                        String key = normalize(item);
                        // Duplicates are ambiguous; reject them rather than assuming availability.
                        if (result.containsKey(key)) result.put(key, new Slots(-1, -1));
                        else result.put(key, new Slots(approved, waiting));
                    }
                    item = null;
                }
            }
        };
        try (Reader reader = new StringReader(html)) { new ParserDelegator().parse(reader, callback, true); }
        return new PvmWarProgress(result);
    }

    Slots lookup(String item)
    {
        if (item == null) return null;
        String key = normalize(item);
        if (key.startsWith("jar of "))
        {
            String name = key.substring("jar of ".length());
            if ("|dreams|spirits|stone|".contains("|" + name + "|")) key = "jar tier 1";
            else if (("|chemicals|decay|sand|souls|swamp|venom|").contains("|" + name + "|")) key = "jar tier 2";
            else if (("|dirt|eyes|feathers|light|miasma|smoke|").contains("|" + name + "|")) key = "jar tier 3";
        }
        Slots slots = items.get(key);
        return slots == null || slots.approved < 0 ? null : slots;
    }

    /** Live item names and recognized jar aliases; ambiguous grouped pets are not guessed. */
    java.util.Set<String> availableItems()
    {
        java.util.Set<String> result = new java.util.LinkedHashSet<>();
        for (Map.Entry<String, Slots> entry : items.entrySet())
        {
            String name = entry.getKey(); Slots slots = entry.getValue();
            if (slots.approved < 0 || slots.approved >= 3 || name.startsWith("jar tier ") || name.startsWith("pet tier ")
                || name.length() > 100 || name.indexOf(';') >= 0 || name.chars().anyMatch(Character::isISOControl)) continue;
            result.add(name);
        }
        String[] jars = {"dreams", "spirits", "stone", "chemicals", "decay", "sand", "souls", "swamp", "venom",
            "dirt", "eyes", "feathers", "light", "miasma", "smoke"};
        for (String jar : jars)
        {
            String name = "jar of " + jar;
            Slots slots = lookup(name);
            if (slots != null && slots.approved < 3) result.add(name);
        }
        return result;
    }

    private static String normalize(String item) { return item.trim().replace('\u2019', '\'').toLowerCase(Locale.ROOT); }
    private static String attr(MutableAttributeSet set, String name)
    {
        for (Enumeration<?> keys = set.getAttributeNames(); keys.hasMoreElements();)
        {
            Object key = keys.nextElement();
            if (name.equalsIgnoreCase(key.toString())) return String.valueOf(set.getAttribute(key));
        }
        return null;
    }

    static final class Slots
    {
        final int approved, waiting;
        Slots(int approved, int waiting) { this.approved = approved; this.waiting = waiting; }
    }
}

package nl.dutchnations.server;

import com.sun.net.httpserver.HttpServer;
import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import org.junit.Test;
import static org.junit.Assert.*;

public class DropTestAuthorizationTest
{
    @Test public void onlyOwnerCanSubmitAndRejectedDropDoesNotChangeState() throws Exception
    {
        Path path = Files.createTempDirectory("dutch-drop-auth-test").resolve("state.json");
        DutchNationsApi.Store store = new DutchNationsApi.Store(path);
        String adminToken = "local-test-admin";
        byte[] digest = MessageDigest.getInstance("SHA-256").digest(adminToken.getBytes(java.nio.charset.StandardCharsets.UTF_8));
        StringBuilder hash = new StringBuilder();
        for (byte value : digest) hash.append(String.format("%02x", value));
        store.saveRole("Admin", "ADMINISTRATOR", hash.toString());
        DutchNationsApi.Event event = new DutchNationsApi.Event();
        event.id = "test-event";
        event.startsAt = java.time.OffsetDateTime.now().minusHours(1).toString();
        event.endsAt = java.time.OffsetDateTime.now().plusHours(1).toString();
        event.codeword = "LOKAAL-TESTWOORD";
        // This test verifies authorization and the unavailable-bot path. It must
        // not depend on the finished public PvM War page being available.
        event.dropSource = "";
        event.dropItems = "Dragon claws;Twisted bow";
        store.addEvent(event);
        Constructor<DutchNationsApi> constructor = DutchNationsApi.class.getDeclaredConstructor(DutchNationsApi.Store.class, String.class);
        constructor.setAccessible(true);
        DutchNationsApi api = constructor.newInstance(store, "local-test-owner");
        Method handler = DutchNationsApi.class.getDeclaredMethod("dropTest", com.sun.net.httpserver.HttpExchange.class);
        handler.setAccessible(true);
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        server.createContext("/api/drop-test", exchange -> {
            try { handler.invoke(api, exchange); }
            catch (ReflectiveOperationException ex) { throw new java.io.IOException(ex); }
        });
        Method settings = DutchNationsApi.class.getDeclaredMethod("dropChannel", com.sun.net.httpserver.HttpExchange.class);
        settings.setAccessible(true);
        server.createContext("/api/drop-channel", exchange -> {
            try { settings.invoke(api, exchange); }
            catch (ReflectiveOperationException ex) { throw new java.io.IOException(ex); }
        });
        server.start();
        try
        {
            URI url = URI.create("http://127.0.0.1:" + server.getAddress().getPort() + "/api/drop-test");
            String body = "{\"eventId\":\"test-event\",\"rsn\":\"Q-Dance Jr\",\"item\":\"Dragon claws\",\"quantity\":1,\"screenshot\":\"iVBORw0KGgo=\"}";
            assertEquals(405, request(url, null, body, false));
            assertEquals(403, request(url, null, body, true));
            assertEquals(403, request(url, adminToken, body, true));
            assertEquals(400, request(url, "local-test-owner", "{}", true));
            assertEquals(409, request(url, "local-test-owner", body.replace("Dragon claws", "Other item"), true));
            assertEquals(409, request(url, "local-test-owner", body, true));
            URI settingUrl = URI.create("http://127.0.0.1:" + server.getAddress().getPort() + "/api/drop-channel");
            String setting = "{\"url\":\"https://discord.com/channels/1239712812822167688/1548661330209280060\"}";
            assertEquals(403, request(settingUrl, adminToken, setting, true));
            assertEquals(200, request(settingUrl, "local-test-owner", setting, true));
            assertEquals(405, request(settingUrl, "local-test-owner", "", false));
            assertEquals("https://discord.com/channels/1239712812822167688/1548661330209280060", store.dropChannelUrl());
            assertEquals(store.dropChannelUrl(), new DutchNationsApi.Store(path).dropChannelUrl());
            byte[] before = Files.readAllBytes(path);
            assertEquals(409, request(url, "local-test-owner", body, true));
            assertArrayEquals(before, Files.readAllBytes(path));
            DutchNationsApi.Store afterRestart = new DutchNationsApi.Store(path);
            assertEquals("LOKAAL-TESTWOORD", afterRestart.event("test-event").codeword);
            assertEquals("ADMINISTRATOR", afterRestart.actorForHash(hash.toString()).role);
        }
        finally { server.stop(0); }
    }

    @Test public void onlyActiveConfiguredEventItemsAreEligible()
    {
        java.time.OffsetDateTime now = java.time.OffsetDateTime.now();
        DutchNationsApi.Event event = new DutchNationsApi.Event();
        event.startsAt = now.minusMinutes(1).toString();
        event.endsAt = now.plusMinutes(1).toString();
        event.dropSource = "PVM_WAR_2026";
        event.dropItems = "Dragon claws;Osmumten’s fang";
        assertTrue(DutchNationsApi.dropTestEligible(event, "dragon claws", now));
        assertTrue(DutchNationsApi.dropTestEligible(event, "Osmumten's fang", now));
        assertFalse(DutchNationsApi.dropTestEligible(event, "Twisted bow", now));
        assertFalse(DutchNationsApi.dropTestEligible(event, "Dragon claws", now.plusMinutes(2)));
        event.dropSource = "";
        assertFalse(DutchNationsApi.dropTestEligible(event, "Dragon claws", now));
    }

    private static int request(URI url, String token, String body, boolean post) throws Exception
    {
        HttpRequest.Builder request = HttpRequest.newBuilder(url);
        if (token != null) request.header("Authorization", "Bearer " + token);
        if (post) request.POST(HttpRequest.BodyPublishers.ofString(body)); else request.GET();
        return HttpClient.newHttpClient().send(request.build(), HttpResponse.BodyHandlers.discarding()).statusCode();
    }
}

package nl.dutchnations.server;

import java.util.Base64;
import org.junit.Test;
import static org.junit.Assert.*;

public class DropTestValidationTest
{
    private static DutchNationsApi.DropTestReport report()
    {
        DutchNationsApi.DropTestReport report = new DutchNationsApi.DropTestReport();
        report.eventId = "test-event";
        report.rsn = "Q-Dance Jr";
        report.item = "Dragon claws";
        report.quantity = 1;
        report.screenshot = Base64.getEncoder().encodeToString(new byte[] {
            (byte) 0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0
        });
        return report;
    }

    @Test public void acceptsImageWithSafeDropMetadata()
    {
        assertNotNull(DutchNationsApi.validateDropTest(report()));
    }

    @Test public void rejectsMissingOrUnsafeData()
    {
        assertNull(DutchNationsApi.validateDropTest(null));
        DutchNationsApi.DropTestReport invalid = report();
        invalid.rsn = "@everyone";
        assertNull(DutchNationsApi.validateDropTest(invalid));
        invalid = report(); invalid.item = "<@123>";
        assertNull(DutchNationsApi.validateDropTest(invalid));
        invalid = report(); invalid.quantity = 0;
        assertNull(DutchNationsApi.validateDropTest(invalid));
        invalid = report(); invalid.eventId = "";
        assertNull(DutchNationsApi.validateDropTest(invalid));
        invalid = report(); invalid.screenshot = "not-base64";
        assertNull(DutchNationsApi.validateDropTest(invalid));
        invalid = report(); invalid.screenshot = Base64.getEncoder().encodeToString(new byte[] {1, 2, 3});
        assertNull(DutchNationsApi.validateDropTest(invalid));
        invalid = report(); invalid.screenshot = "A".repeat(5_592_409);
        assertNull(DutchNationsApi.validateDropTest(invalid));
    }
}

package nl.dutchnations.server;

import java.nio.file.Files;
import java.nio.file.Path;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.lang.reflect.Method;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DutchNationsApiSecurityTest
{
    @Test
    public void onlyRevealsBossCodewordWhileEventIsActive() throws Exception
    {
        Path directory = Files.createTempDirectory("dutch-nations-api-test");
        DutchNationsApi.Store store = new DutchNationsApi.Store(directory.resolve("state.json"));
        OffsetDateTime now = OffsetDateTime.now(ZoneOffset.UTC);

        DutchNationsApi.Event future = event("future", now.plusHours(1), now.plusHours(2), "GEHEIM");
        DutchNationsApi.Event active = event("active", now.minusMinutes(1), now.plusHours(1), "ACTIEF");
        store.addEvent(future);
        store.addEvent(active);

        DutchNationsApi.Feed feed = store.feed();
        assertEquals("", feed.events.get(0).codeword);
        assertEquals("ACTIEF", feed.events.get(1).codeword);
    }

    @Test
    public void detectsOverlappingEventsButNotAdjacentEvents() throws Exception
    {
        Path directory = Files.createTempDirectory("dutch-nations-conflict-test");
        DutchNationsApi.Store store = new DutchNationsApi.Store(directory.resolve("state.json"));
        OffsetDateTime now = OffsetDateTime.now(ZoneOffset.UTC).plusHours(1);
        DutchNationsApi.Event existing = event("existing", now, now.plusHours(2), "GEHEIM");
        store.addEvent(existing);
        assertEquals("existing", store.findConflict(event("overlap", now.plusMinutes(30), now.plusHours(3), "")).id);
        assertEquals(null, store.findConflict(event("adjacent", now.plusHours(2), now.plusHours(3), "")));
    }

    @Test
    public void roleOverviewContainsMetadataButNoTokenHashes() throws Exception
    {
        Path directory = Files.createTempDirectory("dutch-nations-role-overview-test");
        DutchNationsApi.Store store = new DutchNationsApi.Store(directory.resolve("state.json"));
        store.saveRole("Koenb1", "MANAGER", "secret-hash");
        DutchNationsApi.Member member = store.roles().stream().filter(value -> "Koenb1".equals(value.rsn)).findFirst().get();
        assertEquals("MANAGER", member.role);
        assertTrue(member.updatedAt != null && !member.updatedAt.isEmpty());
    }

    @Test
    public void eventStandingsLinksAcceptWebsitesAndRemainAvailableAfterRestart() throws Exception
    {
        Method validate = DutchNationsApi.class.getDeclaredMethod("validateEvent", DutchNationsApi.Event.class);
        validate.setAccessible(true);
        OffsetDateTime now = OffsetDateTime.now(ZoneOffset.UTC);
        DutchNationsApi.Event event = event("standings", now.minusMinutes(1), now.plusHours(1), "CODE");
        event.host = "Q-Dance Jr";

        for (String link : new String[]{"", "https://drive.google.com/file/d/example/view", "https://docs.google.com/spreadsheets/d/example", "https://osrs-nlbe.com/author/dutch_nation/pvm-war-2026/", "http://example.org/standings"})
        {
            event.driveUrl = link;
            assertEquals("Link should be valid: " + link, null, validate.invoke(null, event));
        }

