    private static String strategyWikiUrl(String name, List<ClanFeed.LearnerTemplate> templates)
    {
        for (ClanFeed.LearnerTemplate template : templates)
            if (name != null && name.trim().equals(template.name == null ? "" : template.name.trim())) return value(template.strategyWikiUrl);
        return strategyWikiUrl(name);
    }

    private static String value(String text) { return text == null ? "" : text; }

    static void configureDropSource(EventDraft draft, ClanFeed.ClanEvent existing)
    {
        // Keep old saved data for the live server and older clients, despite hiding the inputs.
        draft.dropItems = existing == null ? "" : value(existing.dropItems);
        draft.dropChannelUrl = existing == null ? "" : value(existing.dropChannelUrl);
        String link = value(draft.dropListUrl).trim();
        if (pvmWarLink(link)) draft.dropSource = "PVM_WAR_2026";
        else if (existing != null && link.equals(value(existing.dropListUrl == null ? existing.driveUrl : existing.dropListUrl).trim())) draft.dropSource = value(existing.dropSource);
        else draft.dropSource = "";
    }

    private static boolean pvmWarLink(String link)
    {
        try
        {
            java.net.URI uri = java.net.URI.create(link);
            String path = uri.getPath();
            return "https".equalsIgnoreCase(uri.getScheme()) && "osrs-nlbe.com".equalsIgnoreCase(uri.getHost())
                && uri.getUserInfo() == null && (uri.getPort() == -1 || uri.getPort() == 443)
                && ("/author/dutch_nation/pvm-war-2026".equals(path) || "/author/dutch_nation/pvm-war-2026/".equals(path));
        }
        catch (RuntimeException ex) { return false; }
    }

    static LocalDateTime parseDateTime(String value, String fieldName)
    {
        String text = value == null ? "" : value.trim();
        for (DateTimeFormatter formatter : ACCEPTED_INPUTS)
        {
            try { return LocalDateTime.parse(text, formatter); }
            catch (DateTimeParseException ignored) { }
        }
        throw new IllegalArgumentException("Controleer de " + fieldName + ". Gebruik bijvoorbeeld 2026-08-01 20:00.");
    }

    private static void repackParentWindow(JPanel form)
    {
        Window window = SwingUtilities.getWindowAncestor(form);
        if (window != null)
        {
            window.pack();
            window.setLocationRelativeTo(null);
        }
    }

    private static JPanel dateTimeFields(JTextField date, JTextField time)
    {
        JPanel fields = new JPanel(new GridLayout(1, 2, 6, 0));
        fields.add(date); fields.add(time); return fields;
    }

    private static JPanel row(String label, java.awt.Component field)
    {
        JPanel row = new JPanel(new GridLayout(1, 2, 6, 6));
        row.add(new JLabel(label)); row.add(field);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
        return row;
    }

