    static final String EVENTS_URL = API_BASE_URL + "/api/events";
    static final String ROLES_URL = API_BASE_URL + "/api/roles";
    static final String ANNOUNCEMENT_CHANNEL_URL = API_BASE_URL + "/api/announcement-channel";
