package nl.dutchnations.events;

import java.time.OffsetDateTime;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

final class WomCompetition
{
    int id;
    String title;
    String metric;
    String startsAt;
    String endsAt;
    // Supplied by Wise Old Man and retained when parsing their response.
    @SuppressWarnings("unused") int participantCount;

    OffsetDateTime start() { return OffsetDateTime.parse(startsAt); }
    OffsetDateTime end() { return OffsetDateTime.parse(endsAt); }
    boolean active(OffsetDateTime now) { return !now.isBefore(start()) && now.isBefore(end()); }

    static List<WomCompetition> visible(List<WomCompetition> competitions, OffsetDateTime now)
    {
        if (competitions == null) return Collections.emptyList();
        List<WomCompetition> candidates = competitions.stream()
            .filter(competition -> competition != null && competition.startsAt != null && competition.endsAt != null)
            .filter(competition -> competition.end().isAfter(now))
            .sorted(Comparator.comparing((WomCompetition competition) -> !competition.active(now))
                .thenComparing(WomCompetition::start))
            .collect(Collectors.toList());
        if (candidates.isEmpty()) return Collections.emptyList();
        List<WomCompetition> visible = candidates.stream()
            .filter(competition -> competition.active(now)).collect(Collectors.toList());
        candidates.stream().filter(competition -> !competition.active(now)).findFirst().ifPresent(visible::add);
        return visible;
    }
}

package nl.dutchnations.events;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.Arrays;
import java.util.List;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

final class WomCompetitionService
{
    static final String GROUP_URL = "https://wiseoldman.net/groups/1476";
    private static final String API_URL = "https://api.wiseoldman.net/v2/groups/1476/competitions?limit=50";
    private final OkHttpClient client;
    private final Gson gson;

    WomCompetitionService(OkHttpClient client, Gson gson) { this.client = client; this.gson = gson; }

    void fetch(Listener listener)
    {
        Request request = new Request.Builder().url(API_URL)
            .header("User-Agent", "Dutch-Nations-RuneLite-Plugin").get().build();
        client.newCall(request).enqueue(new Callback()
        {
            @Override public void onFailure(@javax.annotation.Nonnull Call call, @javax.annotation.Nonnull IOException exception) { listener.failure(); }
            @Override public void onResponse(@javax.annotation.Nonnull Call call, @javax.annotation.Nonnull Response response)
            {
                try (Response closeable = response)
                {
                    if (!response.isSuccessful() || response.body() == null) { listener.failure(); return; }
                    WomCompetition[] responseValues = gson.fromJson(response.body().charStream(), WomCompetition[].class);
                    List<WomCompetition> values = responseValues == null
                        ? java.util.Collections.emptyList()
                        : Arrays.asList(responseValues);
                    listener.success(WomCompetition.visible(values, java.time.OffsetDateTime.now()));
                }
                catch (RuntimeException exception) { listener.failure(); }
            }
        });
    }

    interface Listener
    {
        void success(List<WomCompetition> competitions);
        void failure();
    }
}

package nl.dutchnations.events;

import java.time.OffsetDateTime;
import org.junit.Test;
import static org.junit.Assert.*;

public class DropMatcherTest
{
    @Test public void onlyMatchesSelectedItemsDuringEvent()
    {
        OffsetDateTime now = OffsetDateTime.now();
        ClanFeed.ClanEvent event = new ClanFeed.ClanEvent();
        event.startsAt = now.minusMinutes(1).toString(); event.endsAt = now.plusMinutes(1).toString();
        event.dropItems = "Dragon claws; Twisted bow";
        assertTrue(DropMatcher.matches(event, "dragon CLAWS", now));
        assertFalse(DropMatcher.matches(event, "Dragon claw", now));
        assertFalse(DropMatcher.matches(event, "Twisted bow", now.plusMinutes(2)));
        assertFalse(DropMatcher.matches(event, "Twisted bow", now.minusMinutes(2)));
        assertFalse(DropMatcher.matches(event, null, now));
        event.dropItems = "Karil’s coif";
        assertTrue(DropMatcher.matches(event, "Karil's coif", now));
    }

    @Test public void sourceSnapshotContainsBothItemAndBarrowsNames() throws Exception
    {
        try (java.io.InputStream stream = getClass().getResourceAsStream("/pvm-war-2026-drops.txt"))
        {
            assertNotNull(stream);
            String list = new String(stream.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8);
            assertTrue(list.contains("Dragon claws"));
            assertTrue(list.contains("Karil’s coif"));
            assertTrue(list.length() < 12000);
        }
    }

    @Test public void sheetNamesOverrideManualNamesAndRequireAnActiveEvent()
    {
        OffsetDateTime now = OffsetDateTime.now();
        ClanFeed.ClanEvent event = new ClanFeed.ClanEvent();
        event.startsAt = now.minusMinutes(1).toString(); event.endsAt = now.plusMinutes(1).toString();
        event.dropItems = "Old item";
        assertTrue(DropMatcher.matches(event, "Abyssal whip; Dragon pickaxe", "abyssal whip", now));
        assertFalse(DropMatcher.matches(event, "Abyssal whip", "Old item", now));
        assertFalse(DropMatcher.matches(event, null, "Abyssal whip", now));
        assertFalse(DropMatcher.matches(event, "Abyssal whip", "Abyssal whip", now.plusMinutes(2)));
    }

    @Test public void onlyAcceptsRealGoogleSheetsLinks()
    {
        String id = "1CbSSkKPdpghw9mhFW1yPkv7cXtZrrgEA8r49Yr_nQdQ";
        assertTrue(GoogleSheetLink.supported("https://docs.google.com/spreadsheets/d/" + id + "/edit?gid=1"));
        assertFalse(GoogleSheetLink.supported("https://docs.google.com.evil.test/spreadsheets/d/" + id));
        assertFalse(GoogleSheetLink.supported("http://docs.google.com/spreadsheets/d/" + id));
    }
}

